impl Request {
    /// HTTP method and path of the request, using the most specific URL for the path parameters that are set.
    fn url(&self) -> (crate::http::Method, String) {
        (
            crate::http::Method::Get,
            format!(
                "/{}/_doc/{}",
                crate::typed::support::path_part(&self.index),
                crate::typed::support::path_part(&self.id)
            ),
        )
    }

    /// HTTP method of the request.
    pub fn method(&self) -> crate::http::Method {
        self.url().0
    }

    /// Path of the request, with path parameters percent-encoded.
    pub fn path(&self) -> String {
        self.url().1
    }

    /// Query string parameters of the request.
    pub fn query(&self) -> Vec<(&'static str, String)> {
        let mut query = Vec::new();
        if let Some(value) = &self.force_synthetic_source {
            query.push((
                "force_synthetic_source",
                crate::typed::support::query_value(value),
            ));
        }
        if let Some(value) = &self.preference {
            query.push(("preference", crate::typed::support::query_value(value)));
        }
        if let Some(value) = &self.realtime {
            query.push(("realtime", crate::typed::support::query_value(value)));
        }
        if let Some(value) = &self.refresh {
            query.push(("refresh", crate::typed::support::query_value(value)));
        }
        if let Some(value) = &self.routing {
            query.push(("routing", crate::typed::support::query_value(value)));
        }
        if let Some(value) = &self.route_slice {
            query.push(("_slice", crate::typed::support::query_value(value)));
        }
        if let Some(value) = &self.source {
            query.push(("_source", crate::typed::support::query_value(value)));
        }
        if let Some(value) = &self.source_excludes {
            query.push((
                "_source_excludes",
                crate::typed::support::query_value(value),
            ));
        }
        if let Some(value) = &self.source_exclude_vectors {
            query.push((
                "_source_exclude_vectors",
                crate::typed::support::query_value(value),
            ));
        }
        if let Some(value) = &self.source_includes {
            query.push((
                "_source_includes",
                crate::typed::support::query_value(value),
            ));
        }
        if let Some(value) = &self.stored_fields {
            query.push(("stored_fields", crate::typed::support::query_value(value)));
        }
        if let Some(value) = &self.version {
            query.push(("version", crate::typed::support::query_value(value)));
        }
        if let Some(value) = &self.version_type {
            query.push(("version_type", crate::typed::support::query_value(value)));
        }
        if let Some(value) = &self.error_trace {
            query.push(("error_trace", crate::typed::support::query_value(value)));
        }
        if let Some(value) = &self.filter_path {
            query.push(("filter_path", crate::typed::support::query_value(value)));
        }
        if let Some(value) = &self.human {
            query.push(("human", crate::typed::support::query_value(value)));
        }
        if let Some(value) = &self.pretty {
            query.push(("pretty", crate::typed::support::query_value(value)));
        }
        query
    }

    pub(crate) async fn send(
        self,
        client: &crate::Elasticsearch,
    ) -> std::result::Result<Response, crate::Error> {
        use crate::http::{headers::HeaderMap, request::JsonBody};
        let (method, path) = self.url();
        let query = self.query();
        let response = client
            .transport()
            .send(
                method,
                &path,
                HeaderMap::new(),
                Some(&query),
                None::<JsonBody<()>>,
                None,
            )
            .await?
            .error_for_status_code()?;
        response.json().await
    }
}

#[derive(Debug, Clone, PartialEq, serde::Serialize, serde::Deserialize)]
#[serde(untagged)]
pub enum RequestFilterPath {
    String(String),
    StringList(Vec<String>),
}

impl From<String> for RequestFilterPath {
    fn from(value: String) -> Self {
        RequestFilterPath::String(value)
    }
}

impl From<Vec<String>> for RequestFilterPath {
    fn from(value: Vec<String>) -> Self {
        RequestFilterPath::StringList(value)
    }
}

impl From<&str> for RequestFilterPath {
    fn from(value: &str) -> Self {
        RequestFilterPath::String(value.into())
    }
}

